<script setup lang="ts">
import { t as uiText } from '@/locales'

import { computed, onBeforeUnmount, ref, watch } from 'vue'
import { onBeforeRouteLeave, useRoute, useRouter } from 'vue-router'
import { ElMessageBox } from 'element-plus'
import { operationAction, operationCapabilities, operationDetail, operationPage, operationTarget, type OperationCapabilities, type OperationKind } from '@/api/modules/partnerOperations'
import { newRequestId } from '@/api/modules/partner'
import { partnerError } from '@/utils/partnerError'
import type { BusinessData, BusinessField, PartnerRow } from '@/types/partner'
import BusinessFields from '../BusinessFields.vue'
import PartnerFacts from '../PartnerFacts.vue'
import PartnerPhoto from '../PartnerPhoto.vue'
import OperationFiles from './OperationFiles.vue'
import PartnerOperationCreate from './PartnerOperationCreate.vue'
import PartnerOperationsPanel from './PartnerOperationsPanel.vue'
import FactorySignature from './FactorySignature.vue'
import InspectionResult from './InspectionResult.vue'
import { moneyOrUnknown, operationLabel } from './presentation'
const props = defineProps<{ kind: OperationKind; id: number }>()
const route = useRoute(), router = useRouter(), record = ref<PartnerRow>(), capabilities = ref<OperationCapabilities>(), loading = ref(false), error = ref(''), busy = ref(false)
const action = ref(''), form = ref<BusinessData>({}), formError = ref(''), dirty = ref(false), signing = ref(false), copyQuote = ref(false), feeCreate = ref(false)
const refs = ref<BusinessData[]>([]), qcChoices = ref<BusinessData[]>([]), files = ref<InstanceType<typeof OperationFiles>>(), dialogFiles=ref<InstanceType<typeof OperationFiles>>(),fieldErrors=ref<Record<string,string>>({})
const copyForm=ref<InstanceType<typeof PartnerOperationCreate>>(),feeForm=ref<InstanceType<typeof PartnerOperationCreate>>()
watch(refs,()=>{if(action.value&&!loading.value)dirty.value=true},{deep:true})
let generation = 0
async function load() { const ticket = ++generation; loading.value = true; error.value = ''; try { const [d, c] = await Promise.all([operationDetail(props.kind, props.id), operationCapabilities()]); if (ticket !== generation) return; record.value = d; capabilities.value = c; refs.value = [...(d.refs || [])] } catch (e) { if (ticket === generation) error.value = partnerError(e) } finally { if (ticket === generation) loading.value = false } }
watch(() => [props.kind, props.id], () => { record.value = undefined; void load() }, { immediate: true })
onBeforeUnmount(() => { generation++ })
const engineering = computed(() => !!capabilities.value?.engineering)
const allowedWrite = computed(() => engineering.value && props.kind !== 'listing' && record.value?.status !== 'closed' && (!['supplier_quote','inspection'].includes(props.kind)||record.value?.status==='draft'))
const materialWrite=computed(()=>allowedWrite.value||(props.kind==='fulfilment'&&capabilities.value?.delivery&&record.value?.status!=='closed'))
const result = computed(() => record.value?.resultSnapshot)
const actions = computed(() => {
  if (!record.value || !capabilities.value || record.value.status === 'closed') return []
  if (props.kind === 'supplier_quote') return engineering.value && record.value.status === 'draft' ? ['save_draft','confirm'] : []
  if (props.kind === 'sample_fee') return engineering.value ? ['agreement', 'charge', 'refund', 'offset', 'reverse'] : []
  if (props.kind === 'inspection') return !engineering.value ? [] : record.value.status === 'draft' ? ['save_draft','confirm'] : record.value.status === 'pending_signature' ? ['sign', 'pending_signature'] : result.value?.result === 'pass' && record.value.sourceKind === 'sample' ? ['reference'] : []
  if (props.kind === 'fulfilment') return [...(engineering.value ? [...(record.value.status==='pending'?['accept']:['delay']),...(!record.value.actualCompletedDate&&record.value.status!=='pending'?['complete']:[]),'change',...(record.value.status!=='pending'&&record.value.status!=='received'?['dispatch']:[]),'expense','close'] : []), ...(capabilities.value.delivery ? ['receipt', 'after_sales'] : [])]
  return []
})
const actionTitle = (a: string) => ({ save_draft:'编辑未完成草稿', confirm: props.kind === 'inspection' ? '填写检查并自行确认' : '确认本版报价依据', pending_signature: '记录待签原因', charge: '登记实际样品费', refund: '登记直接退款', offset: '登记抵扣大货款', reverse: '追加冲回更正', agreement: '补充本次约定', reference: '指定原样品为对照', sign: '请工厂代表现场签字', accept: '记录工厂接单', delay: '更新预计出厂时间', complete: '记录实际完工', change: '记录需求变更', dispatch: '登记已放行发运', receipt: '登记实际收货', after_sales: '质量／交付异常跟进', expense: '记录逐单费用／服务费', close: '结案核对' } as Record<string, string>)[a] || a
const fields = computed<BusinessField[]>(() => {
  const f: BusinessField[] = [], a = action.value
  if(props.kind==='supplier_quote'&&a==='save_draft')return [{key:'specDescription',label:'实际报价型号／规格',type:'textarea'},{key:'supplierItemCode',label:'供方原货号'},{key:'qty',label:'报价数量（未知可留空）',type:'number'},{key:'unitPrice',label:'本版供方单价（未知可留空）',type:'money'},{key:'currency',label:'实际币种（未知可留空）'},{key:'date',label:'实际报价日期',type:'date'},{key:'terms',label:'本版条款与采用说明',type:'textarea'}]
  if (props.kind === 'inspection' && ['confirm','save_draft'].includes(a)) f.push({ key: 'factory', label: '实际到厂检验的工厂', required: true }, { key: 'date', label: '实际检验日期', type: 'date', required: true }, { key: 'checks', label: '实际检查项目、结果／测量值', type: 'textarea', required: true }, { key: 'result', label: '本次检验结论（不预填通过）', type: 'select', required: true, options: (record.value?.sourceKind === 'fulfilment' ? ['pass', 'partial', 'fail'] : ['pass', 'fail']).map(v => ({ value: v, label: operationLabel(v) })) }, { key: 'issues', label: '问题清单（有问题须附照片）', type: 'textarea' }, { key: 'rectification', label: '整改／换样与本次复检说明', type: 'textarea' }, ...(record.value?.sourceKind === 'fulfilment' ? [{ key: 'qualityEvidence', label: '采用的对照样品／质量依据', required: true }, { key: 'isolation', label: '部分放行时明确隔离的依据', type: 'textarea' as const }] : []))
  else if (props.kind === 'inspection' && a === 'reference') f.push({ key: 'location', label: '原样品实际存放位置', required: true }, { key: 'custodian', label: '实际保管人', required: true }, { key: 'date', label: '实际指定日期', type: 'date', required: true }, { key: 'reason', label: '对照用途和适用范围', type: 'textarea', required: true })
  else if (a === 'pending_signature') f.push({ key: 'reason', label: '工厂拒签／代表不在场等真实原因', type: 'textarea', required: true })
  else if (props.kind === 'sample_fee') {
    f.push({ key: 'date', label: '实际日期', type: 'date', required: true }, { key: 'reason', label: '本次实际说明／更正原因', type: 'textarea', required: true })
    if (a === 'agreement') f.push({ key: 'terms', label: '实际收费、可退／可抵和条件', type: 'textarea', required: true }, { key: 'currency', label: '币种（已明确后不可改写）' })
    else if (a === 'reverse') f.push({ key: 'originalEventId', label: '本笔原实际办理记录', type: 'select', required: true, options: (record.value?.events || []).filter((e: BusinessData) => ['fee_charge', 'fee_refund', 'fee_offset'].includes(e.action)).map((e: BusinessData) => ({ value: e.id, label: `${operationLabel(e.action)} · ${e.data.date} · ${moneyOrUnknown(e.data.amountCents, record.value?.currency)}` })) })
    else f.push({ key: 'amount', label: '本次实际金额（不是付款指令）', type: 'money', required: true }, { key: 'payer', label: '实际付款／承担方', required: true }, { key: 'payee', label: '实际收款／抵扣方', required: true }, { key: 'executor', label: '实际经办岗位／人员', required: true }, { key: 'evidence', label: '真实凭据／供应商确认依据', type: 'textarea' }, ...(a === 'offset' ? [{ key: 'bulkReference', label: '抵扣对应的大货结算依据', type: 'textarea' as const, required: true }] : []))
  } else if (props.kind === 'fulfilment') {
    f.push({ key: 'date', label: '实际日期', type: 'date', required: true })
    if (['accept', 'delay'].includes(a)) f.push({ key: 'expectedFactoryDate', label: '本单预计出厂日期（不等于海外到货）', type: 'date', required: true })
    if (a === 'dispatch') f.push({ key: 'tracking', label: '运单／物流依据', required: true }, { key: 'destination', label: '本单约定实际收货点', required: true }, { key: 'evidence', label: '装箱及工厂出货资料依据', type: 'textarea', required: true })
    else if (a === 'receipt') f.push({ key: 'dispatchId', label: '原实际发运记录', type: 'select', required: true, options: (record.value?.events || []).filter((e: BusinessData) => e.action === 'dispatch').map((e: BusinessData) => ({ value: e.id, label: `${e.data.date} · ${e.data.tracking}` })) }, { key: 'specId', label: '实际收货规格', type: 'select', required: true, options: (record.value?.lines || []).map((s: BusinessData) => ({ value: s.specId, label: s.specName })) }, { key: 'qty', label: '本次实际收到数量', type: 'number', required: true }, { key: 'shortage', label: '本次核实短少数量', type: 'number' }, { key: 'difference', label: '短少／破损等差异说明', type: 'textarea' }, { key: 'evidence', label: '实际收货依据', type: 'textarea', required: true })
    else if (a === 'expense') f.push({ key: 'category', label: '本单费用／服务费类别', required: true }, { key: 'terms', label: '本单资金流向、承担和计费实际约定', type: 'textarea', required: true }, { key: 'amount', label: '实际金额（未知留空）', type: 'money' }, { key: 'currency', label: '实际币种（未知留空）' }, { key: 'payer', label: '本单实际付款方', required: true }, { key: 'payee', label: '本单实际收款方', required: true }, { key: 'executor', label: '实际经办岗位／人员', required: true }, { key: 'evidence', label: '真实约定／实际办理依据', type: 'textarea', required: true })
    else f.push({ key: 'reason', label: a === 'close' ? '交付、售后及费用结案核对依据' : '实际情况／变更及处理说明', type: 'textarea', required: true }, ...(a === 'close' ? [] : [{ key: 'evidence', label: '供应商确认／原批次及问题依据', type: 'textarea' as const, required: true }]))
  }
  return a==='save_draft'?f.map(field=>({...field,required:false})):f
})
async function start(a: string) {
  if (a === 'sign') { signing.value = true; return }
  const saved=record.value!.draftResult||{};action.value = a; form.value = { ...saved,version: record.value!.version, requestId: newRequestId(), date: saved.date||new Date().toLocaleDateString('sv-SE'), factory: saved.factory||record.value!.factory || '', currency: record.value!.currency || '', scope: (record.value!.allowedScope || []).map((s: BusinessData) => {const old=(saved.scope||[]).find((row:BusinessData)=>s.catalogSpecKey?row.catalogSpecKey===s.catalogSpecKey:row.specId===s.specId);return { ...s,...old, included: !!old, checkedQty: old?.checkedQty, coveredQty:old?.coveredQty??s.qty, releaseQty: old?.releaseQty??0 }}), allocations: [{}], shortage: 0 }; formError.value = ''; fieldErrors.value={};dirty.value = false
  if(props.kind==='supplier_quote')Object.assign(form.value,{specDescription:record.value!.specDescription,supplierItemCode:record.value!.supplierItemCode,qty:record.value!.qty,unitPrice:record.value!.unitPriceCents===undefined?'':(record.value!.unitPriceCents/100).toFixed(2),terms:record.value!.terms,date:record.value!.date||''})
  if (a === 'dispatch') try { const found = await operationPage('inspection', { parentId: props.id, status: 'signed', size: 100 }); qcChoices.value = found.content.flatMap(qc => (qc.resultSnapshot?.scope || []).filter((s: BusinessData) => s.releaseQty > 0).map((s: BusinessData) => ({ ...s, inspectionId: qc.id, key: `${qc.id}:${s.specId}`, label: `${qc.code} · ${s.specName} · 本次放行 ${s.releaseQty}` }))) } catch (e) { formError.value = partnerError(e) }
}
async function cancel(done?: () => void) { if (dirty.value) try { await ElMessageBox.confirm(uiText('放弃本次未保存的填写？'), uiText('未保存内容')) } catch { return false } action.value = ''; dirty.value = false; done?.(); return true }
onBeforeRouteLeave(async () => !dirty.value || await cancel())
async function save(intent=action.value) {
  if (files.value?.busy || files.value?.error || dialogFiles.value?.busy || dialogFiles.value?.error) { formError.value = '仍有原件上传中或失败，请处理后再确认。'; return }
  fieldErrors.value={};if(intent!=='save_draft')for(const f of fields.value.filter(f=>f.required))if(form.value[f.key]===undefined||form.value[f.key]===null||String(form.value[f.key]).trim()==='')fieldErrors.value[f.key]=`请填写${f.label}`
  if(intent==='confirm'&&props.kind==='inspection'){if(!(form.value.scope||[]).some((s:BusinessData)=>s.included))fieldErrors.value.scope='请明确选择本次检验范围，未列规格不算通过';if(!form.value.onsite)fieldErrors.value.onsite='请实际现场检验后自行确认'}
  if(Object.keys(fieldErrors.value).length){formError.value='请补齐标出的实际资料；尚未完成可以先保存草稿。';return}
  busy.value = true; formError.value = ''
  try { const keys = new Set([...fields.value.map(f => f.key), 'requestId', 'version']); const payload: BusinessData = { ...Object.fromEntries(Object.entries(form.value).filter(([key]) => keys.has(key))), refs: refs.value }
    if (props.kind === 'inspection' && ['confirm','save_draft'].includes(action.value)) { payload.scope = (form.value.scope || []).filter((s: BusinessData) => s.included); payload.onsite = form.value.onsite }
    if (action.value === 'close') for (const key of ['deliveryResolved', 'qualityResolved', 'expensesResolved']) payload[key] = form.value[key]
    if (action.value === 'after_sales') payload.resolved = form.value.resolved
    if (action.value === 'dispatch') payload.allocations = form.value.allocations.map((a: BusinessData) => ({ ...qcChoices.value.find(q => q.key === a.key), qty: a.qty }))
    record.value = await operationAction(props.kind, props.id, intent, payload); action.value = ''; dirty.value = false
  } catch (e) { formError.value = partnerError(e) } finally { busy.value = false }
}
async function refreshFiles() { if (!record.value) return; try { const latest = await operationDetail(props.kind, props.id); record.value.files = latest.files } catch (e) { error.value = partnerError(e) } }
function sourceLink() { if (!record.value?.parentId) return; const kind = record.value.sourceKind || record.value.sourceSnapshot?.kind; void router.push(kind === 'sample' ? { path: '/samples', query: { id: record.value.parentId, from: route.fullPath } } : kind === 'product' ? { path: '/partner-products', query: { id: record.value.parentId, from: route.fullPath } } : operationTarget(kind, record.value.parentId, route.fullPath)) }
function created(row: PartnerRow, kind: OperationKind) { feeCreate.value = false; copyQuote.value = false; void router.push(operationTarget(kind, row.id, route.fullPath)) }
</script>
<template><div class="operation-detail" v-loading="loading"><el-alert v-if="error" :title="error" type="error" :closable="false"><el-button link @click="load">{{ uiText("重新加载") }}</el-button></el-alert><template v-if="record"><div class="identity"><h3>{{ record.name }}</h3><span>{{ record.code }} · V{{ record.version }}</span><el-tag>{{ uiText(operationLabel(record.status)) }}</el-tag><el-button v-if="record.parentId" link @click="sourceLink">{{ uiText("查看原来源") }}</el-button></div><div class="detail-scroll">
<section v-if="kind === 'supplier_quote'" class="panel"><h4>{{ record.supplierName }} · {{ record.supplierCode }}</h4><p>{{ record.specDescription }}</p><p>{{ uiText("原货号 ") }}{{ record.supplierItemCode || uiText('未填') }}{{ uiText(" · 报价数量 ") }}{{ record.qty ?? uiText('待补') }} · {{ moneyOrUnknown(record.unitPriceCents, record.currency) }}</p><p>{{ record.terms || uiText('条款待补，可附原件') }}</p><p class="hint">{{ uiText("原报价保留；报价变化追加新记录，不覆盖已采用依据。") }}</p><el-button v-if="engineering" @click="copyQuote = true">{{ uiText("追加新报价") }}</el-button><el-button v-if="engineering" @click="feeCreate = true">{{ uiText("记录本次样品费约定") }}</el-button></section>
<section v-if="kind === 'sample_fee'" class="panel"><h4>{{ record.supplierName }} · {{ record.terms }}</h4><p>{{ uiText("约定金额 ") }}{{ moneyOrUnknown(record.agreedAmountCents, record.currency) }}{{ uiText("（不是实际已付）") }}</p><div class="fee-totals"><span v-for="(label, key) in { chargedCents: '实际样品费', refundedCents: '直接退款', offsetCents: '抵扣大货款', remainingCents: '尚未抵退' }" :key="key">{{ label }}：{{ moneyOrUnknown(record.balances?.[key], record.currency) }}</span></div></section>
<section v-if="kind === 'inspection' && result" class="panel"><InspectionResult :record="record"/><div v-if="record.factorySignature" class="signature-proof"><span>{{ uiText("本次现场签名") }}</span><PartnerPhoto :id="record.factorySignature.signatureFileId"/></div><p v-if="record.referenceSample">{{ uiText("对照样品仍在原台账：") }}{{ record.referenceSample.location }} · {{ record.referenceSample.custodian }} · {{ record.referenceSample.reason }}</p><el-button v-if="engineering" @click="router.push({ path: '/partner-operations/inspection/'+record.id, query: { ...route.query, reinspect: '1' } }); copyQuote = true">{{ uiText("整改／复检：新增记录") }}</el-button></section>
<section v-if="kind === 'fulfilment'" class="panel"><h4>{{ record.supplierName }}{{ uiText(" · 工厂 ") }}{{ record.factory }}</h4><p>{{ uiText("原确认需求：") }}{{ record.sourceChannel }} · {{ record.sourceReference }}</p><p>{{ record.requirements }}</p><p>{{ uiText("预计出厂 ") }}{{ record.expectedFactoryDate || uiText('待工厂确认') }}{{ uiText(" · 实际完工 ") }}{{ record.actualCompletedDate || uiText('尚未记录') }}</p><ul><li v-for="line in record.lines" :key="line.specId">{{ line.productName }} · {{ line.specName }}{{ uiText(" · 本批 ") }}{{ line.qty }}{{ uiText(" 件") }}</li></ul><p class="hint">{{ uiText("客户确认、工厂接单、完工、检验、签字、发运和收货各自留痕。没有本批有效放行不能发货。") }}</p></section>
<section v-if="kind === 'listing'" class="panel"><el-alert :title="record.reason" type="warning" :closable="false"/><p>{{ uiText("本次销售确认已保存，外部未确认成功，不改变原商品实际销售状态。") }}</p><PartnerFacts :value="record.basis"/></section>
<section v-if="actions.length" class="panel"><h4>{{ uiText("本次办理") }}</h4><div class="actions"><el-button v-for="a in actions" :key="a" size="small" @click="start(a)">{{ actionTitle(a) }}</el-button></div></section>
<section v-if="kind !== 'listing'" class="panel"><OperationFiles ref="files" :kind="kind" :id="id" :files="record.files || []" v-model="refs" :can-write="!!materialWrite" :can-cost="capabilities?.costs" @changed="refreshFiles"/></section>
<PartnerOperationsPanel v-if="kind === 'fulfilment'" kind="inspection" :parent-id="id" :source-name="record.name"/>
<PartnerOperationsPanel v-if="kind === 'supplier_quote'" kind="sample_fee" :parent-id="id" :source-name="record.name"/>
<section class="panel"><h4>{{ uiText("历史记录（原结果、原签名和原费用不覆盖）") }}</h4><details v-for="event in [...(record.events || [])].reverse()" :key="event.id"><summary>{{ uiText(operationLabel(event.action)) }} · {{ event.operator }} · {{ String(event.time).slice(0,19) }}</summary><PartnerFacts :value="event.data"/></details></section>
</div>
<el-dialog :model-value="!!action" :title="actionTitle(action)" width="min(760px,96vw)" :close-on-click-modal="false" :before-close="cancel" append-to-body @close="action = ''"><el-form label-position="top" @input="dirty = true" @change="dirty = true"><OperationFiles v-if="kind!=='listing'" ref="dialogFiles" :kind="kind" :id="id" :files="record.files||[]" v-model="refs" :can-write="!!materialWrite" :can-cost="capabilities?.costs" @changed="refreshFiles"/><BusinessFields :model="form" :fields="fields" :errors="fieldErrors"/>
<template v-if="kind === 'inspection' && ['confirm','save_draft'].includes(action)"><p v-if="fieldErrors.scope" class="inline-error">{{fieldErrors.scope}}</p><p v-if="fieldErrors.onsite" class="inline-error">{{fieldErrors.onsite}}</p><h4>{{ uiText("本次适用范围：请逐项明确，未列入不算通过") }}</h4><div v-for="scope in form.scope" :key="scope.catalogSpecKey||scope.specId" class="scope-line"><el-checkbox v-model="scope.included">{{ scope.specName }}</el-checkbox><template v-if="scope.included"><el-form-item v-if="record.sourceKind==='fulfilment'" :label="uiText('本次明确覆盖批量（原批 ')+scope.qty+'）'"><el-input-number v-model="scope.coveredQty" :min="1" :max="scope.qty" :precision="0"/></el-form-item><el-form-item :label='uiText("实际检查数量")'><el-input-number v-model="scope.checkedQty" :min="1" :precision="0"/></el-form-item><el-form-item v-if="record.sourceKind === 'fulfilment'" :label="uiText('本次可放行数量（批量 ')+scope.qty+'）'"><el-input-number v-model="scope.releaseQty" :min="0" :max="scope.qty" :precision="0"/></el-form-item></template></div><el-checkbox v-model="form.onsite">{{ uiText("本人已实际现场检验，并自行确认以上真实结果") }}</el-checkbox><p class="hint">{{ uiText("可直接在本表单上方上传并勾选实际问题照片／原件。确认后内容冻结，工厂代表再针对本次结果签字。") }}</p></template>
<template v-if="action === 'dispatch'"><div v-for="(allocation, i) in form.allocations" :key="i" class="scope-line"><el-select v-model="allocation.key" :placeholder='uiText("选择本批已签字的明确放行范围")'><el-option v-for="q in qcChoices" :key="q.key" :value="q.key" :label="q.label"/></el-select><el-input-number v-model="allocation.qty" :min="1" :precision="0"/><el-button :disabled="form.allocations.length === 1" @click="form.allocations.splice(i,1)">{{ uiText("移除") }}</el-button></div><el-button @click="form.allocations.push({})">{{ uiText("添加放行分配") }}</el-button></template>
<div v-if="action === 'close'" class="checks"><el-checkbox v-model="form.deliveryResolved">{{ uiText("本单交付已实际核对") }}</el-checkbox><el-checkbox v-model="form.qualityResolved">{{ uiText("本单售后和差异已解决") }}</el-checkbox><el-checkbox v-model="form.expensesResolved">{{ uiText("本单适用费用／服务费已核对") }}</el-checkbox></div><el-checkbox v-if="action === 'after_sales'" v-model="form.resolved">{{ uiText("本次问题已实际解决（不勾选表示仍在跟进）") }}</el-checkbox><el-alert v-if="formError" :title="formError" type="error" :closable="false"/></el-form><template #footer><el-button @click="cancel()">{{ uiText("取消") }}</el-button><el-button v-if="kind==='inspection'&&action==='confirm'" :loading="busy" @click="save('save_draft')">{{ uiText("保存草稿，暂不确认") }}</el-button><el-button type="primary" :loading="busy" @click="save()">{{action==='save_draft'?uiText('保存未完成草稿'):uiText('保存本次实际记录')}}</el-button></template></el-dialog>
<FactorySignature v-if="signing" :record="record" @close="signing = false" @signed="record = $event; signing = false"/>
<el-dialog v-model="copyQuote" :title="kind === 'inspection' ? uiText('整改／复检：保留原结果和原签名') : uiText('追加新报价')" width="min(760px,96vw)" :close-on-click-modal="false" destroy-on-close append-to-body :before-close="()=>copyForm?.close()"><PartnerOperationCreate ref="copyForm" :kind="kind" :supplier-code="record.supplierCode" :parent-id="record.parentId" :source-name="record.name" :previous-id="record.id" @close="copyQuote = false" @saved="created($event,kind)"/></el-dialog>
<el-dialog v-model="feeCreate" :title='uiText("本次样品费实际约定")' width="min(760px,96vw)" :close-on-click-modal="false" destroy-on-close append-to-body :before-close="()=>feeForm?.close()"><PartnerOperationCreate ref="feeForm" kind="sample_fee" :parent-id="id" :source-name="record.name" @close="feeCreate = false" @saved="created($event,'sample_fee')"/></el-dialog>
</template></div></template>
<style scoped>.operation-detail{display:flex;flex-direction:column;gap:8px;min-height:0;min-width:0;flex:1;container-type:inline-size}.identity{display:flex;gap:8px;align-items:center;flex-wrap:wrap;flex:none;font-size:13px;color:#6e7f95}.identity h3{font-size:16px;color:#24374f;margin:0;overflow-wrap:anywhere}.detail-scroll{flex:1;min-height:0;overflow:auto;display:flex;flex-direction:column;gap:10px}.panel{background:#fff;border:1px solid #e5ebf2;padding:12px;border-radius:7px;min-width:0;overflow-wrap:anywhere}.panel h4{font-size:14px;margin:0 0 8px}.panel p,.panel li{font-size:14px;line-height:1.7}.actions,.fee-totals,.signature-proof{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.actions :deep(.el-button){margin:0;white-space:normal;height:auto;line-height:1.6}.hint{font-size:13px;color:#738399;line-height:1.6}.inline-error{font-size:13px;color:var(--el-color-danger);line-height:1.6}.scope-line{display:flex;gap:10px;flex-wrap:wrap;align-items:center;padding:10px 0;border-bottom:1px solid #e8edf4}.scope-line>.el-checkbox{flex-basis:100%;white-space:normal;height:auto}.scope-line :deep(.el-checkbox__label){white-space:normal;overflow-wrap:anywhere;line-height:1.6}.scope-line>.el-select{flex:1;min-width:150px}.checks{display:flex;flex-direction:column}.panel details{font-size:13px;margin-top:10px}.panel summary{cursor:pointer;line-height:1.8}@container(max-width:500px){.identity h3{flex-basis:100%}.panel{padding:10px}}</style>
